    val train: TrainId,
    val generation: Long,
    val capturedAtMillis: Long,
    val speedKmh: Double?,
    val currentMaximumKmh: Double?,
)

fun readSpeed(game: Game, id: TrainId): SpeedSample? {
    val observation = game.trains.read(id) ?: return null
    val measured = observation.speedMps.takeUnless { observation.speedDefaulted }
    return SpeedSample(
        id, observation.sessionGeneration, observation.capturedAtMillis,
        measured?.times(3.6), observation.currentDynamics?.maxSpeedMps?.times(3.6),
    )
}

package wiki.trackpositions

import fr.nimby.sdk.Observation
import fr.nimby.sdk.Position
import fr.nimby.sdk.TrackDirection
import fr.nimby.sdk.TrackId

class TrackPositions(snapshot: Observation) {
    private val metrics = snapshot.trackMetrics?.associateBy { it.trackId }

    fun atMetres(track: TrackId, offsetM: Double, direction: TrackDirection): Position? {
        val metric = metrics?.get(track.value) ?: return null
        if (!offsetM.isFinite() || offsetM !in 0.0..metric.lengthM) return null
        return metric.positionAtMetres(offsetM, direction)
    }
}

package wiki.constructiontickets

import fr.nimby.sdk.ConstructionResult
import fr.nimby.sdk.ConstructionState
import fr.nimby.sdk.Game
import fr.nimby.sdk.Position

class ConfirmedPlacement(
    private val game: Game,
    private val sourceSignal: Long,
    confirmedPositions: List<Position>,
) {
    private val positions = confirmedPositions.toList()
    var ticket: Long? = null
        private set
    private var prepareSubmitted = false
    private var submitted = false
    private var undoSubmitted = false

    fun prepare(): ConstructionResult {
        check(!prepareSubmitted)
        prepareSubmitted = true
        val result = game.construction.prepare(sourceSignal)
        if (result.token != 0L) ticket = result.token
        return result
    }

    fun createOnce(): ConstructionResult {
        val token = checkNotNull(ticket)
        check(!submitted)
        val current = game.construction.poll(token)
        if (current.state != ConstructionState.READY) return current
        submitted = true
        return game.construction.create(token, sourceSignal, positions)
    }

    fun inspect(): ConstructionResult = game.construction.poll(checkNotNull(ticket))

    fun undoIfAvailable(): ConstructionResult {
        val token = checkNotNull(ticket)
        check(!undoSubmitted)
        val current = game.construction.poll(token)
        if (!current.canUndo) return current
        undoSubmitted = true
        return game.construction.undo(token)
    }
}

