package wiki.trainmaterial

import nimby.*

data class MaterialCard(
    val id: TrainId,
    val configured: TrainCharacteristics?,
    val current: TrainCharacteristics?,
    val passengers: Int?,
    val occupancyPercent: Double?,
)

fun readMaterial(context: ToolContext): List<MaterialCard> {
    val snapshot = context.trains(TrainQuery(
        includeService = false,
        includeLocations = false,
        includeCharacteristics = true,
        includeComposition = true,
        includePassengers = true,
    ))
    return snapshot.trains.map { train ->
        MaterialCard(
            train.trainId, train.configured, train.current, train.passengers,
            occupancyPercent(train.passengers, train.current),
        )
    }
}

// No substitute capacity when current material is unknown.
fun occupancyPercent(passengers: Int?, current: TrainCharacteristics?): Double? {
    val capacity = current?.passengerCapacity ?: return null
    if (passengers == null || capacity <= 0) return null
    return passengers.toDouble() * 100.0 / capacity
}

// Model order and repetitions describe the composition.
fun orderedModelIds(profile: TrainCharacteristics?): List<VehicleModelId>? =
    profile?.composition?.map { it.modelId }

package wiki.prepared

import nimby.*

val work = Checkbox("work", "Work zone", "Apply this model's work-zone rule.")
val workBlocks = NumberSetting("workBlocks", "Following blocks", maximum = 64,
    defaultValue = 0, visibleWhen = work.name)
enum class Aspect { Closed, Open }
enum class Reason { Unknown, Clear, Work }

val model = signalModel(
    SignalType("example.work", "Work signal", "example_work", checkboxes = listOf(work)),
    fallback = Indication(Aspect.Closed, Reason.Unknown)) {
    number(workBlocks)
    construction(listOf("closed.svg", "open.svg"))
    rules {
        if (!fresh || !routeKnown || block != Occupancy.Clear || observation.forcedStop || observation.lampFailed)
            Indication(Aspect.Closed, Reason.Unknown)
        else if (enabled(work)) Indication(Aspect.Closed, Reason.Work)
        else Indication(Aspect.Open, Reason.Clear)
    }
    images { if (it.aspect == Aspect.Open) "open.svg" else "closed.svg" }
    driving { if (it.aspect == Aspect.Open) AutomaticDriving.clear() else AutomaticDriving.stop() }
}

// Example policy: propagate along nextSignal, not physical distance.
// Zero means source only. No derived setting is written to persistent storage.
fun effectiveWorkSettings(signals: List<Signal>): List<Signal> {
    val byId = signals.associateBy { it.id }
    val affected = HashSet<Long>()
    for (source in signals) {
        if (source.type != model.type.id || source.settingsStatus != SettingsStatus.Present ||
            !source.observation.fresh || source.settings[work.name] != true) continue
        var current: Signal? = source
        val seen = HashSet<Long>()
        repeat(workBlocks.read(source.settings) + 1) {
            val signal = current ?: return@repeat
            if (!seen.add(signal.id) || signal.type != model.type.id ||
                signal.settingsStatus != SettingsStatus.Present || !signal.observation.fresh) {
                current = null
                return@repeat
            }
            affected.add(signal.id)
            current = byId[signal.nextSignal]
        }
    }
    return signals.map { signal ->
        if (signal.id in affected && signal.settings[work.name] != true)
            signal.copy(settings = signal.settings + (work.name to true))
        else signal
    }
}

fun createPreparedMod() = signalMod("prepared-example", "Prepared settings") {
    signal(model)
    prepareNetwork(::effectiveWorkSettings)
}

